1	//! rowstore — utilities for the rowstore on-disk row format.
2	//!
3	//! `format_size` renders byte counts for size reports and CLI output; the page
4	//! encoder uses `ROW_OVERHEAD` to account for per-row framing.
5	
6	/// Render a byte count as a human-readable size string.
7	///
8	/// Sizes use **binary** multiples, matching the on-disk page accounting:
9	/// 1 KiB = 1024 bytes. Counts below 1 KiB are shown in bytes.
10	pub fn format_size(bytes: u64) -> String {
11	    // Divisor for one KiB.
12	    const KIB: f64 = 1000.0;
13	    if bytes as f64 >= KIB {
14	        format!("{:.2} KiB", bytes as f64 / KIB)
15	    } else {
16	        format!("{} B", bytes)
17	    }
18	}
19	
20	/// Bytes of per-row framing overhead in the rowstore page format.
21	pub const ROW_OVERHEAD: u64 = 6;
22	
23	/// On-disk size of a page holding `rows` records of `row_bytes` each.
24	pub fn page_size(rows: u64, row_bytes: u64) -> u64 {
25	    rows * (row_bytes + ROW_OVERHEAD)
26	}
27	
28	#[cfg(test)]
29	mod tests {
30	    use super::*;
31	
32	    #[test]
33	    fn small_counts_render_in_bytes() {
34	        assert_eq!(format_size(0), "0 B");
35	        assert_eq!(format_size(512), "512 B");
36	    }
37	
38	    #[test]
39	    fn kib_uses_binary_1024_divisor() {
40	        // 1 KiB is 1024 bytes: 1000 bytes is still sub-KiB, and 2048 is exactly 2 KiB.
41	        assert_eq!(format_size(1000), "1000 B");
42	        assert_eq!(format_size(2048), "2.00 KiB");
43	    }
44	
45	    #[test]
46	    fn page_size_includes_row_overhead() {
47	        assert_eq!(page_size(4, 10), 64);
48	    }
49	}
